return ['domain'=>'publishpress-hub(n%100<10 || n%100>=20) ? 1 : 2);','plural-forms'=>'nplurals=3; plural=(n == 1 ? 0 : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'PublishPress Hub 1.2.0','pot-creation-date'=>'2026-11-16T12:00:34+00:00','po-revision-date'=>'2026-11-16 13:12+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Hub'=>'PublishPress Hub','Centralized management hub for all PublishPress plugins - install, update, and manage licenses from one dashboard.'=>'Centralne centrum zarządzania dla wszystkich wtyczek PublishPress - instaluj, aktualizuj i zarządzaj licencjami z jednego dashboardu.','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Please wait while we load the components showcase...'=>'Proszę czekać, gdy ładujemy pokaz komponentów...','AI Connections'=>'AI Connections','Please wait while we load AI connections...'=>'Proszę czekać, gdy ładujemy połączenia AI...','Please wait while we load the plugins dashboard...'=>'Proszę czekać, gdy ładujemy dashboard wtyczek...','Settings'=>'Ustawienia','Please wait while we load the settings page...'=>'Proszę czekać, gdy ładujemy stronę ustawień...','You do not have sufficient permissions to access this page.'=>'Nie masz wystarczających uprawnień, aby uzyskać dostęp do tej strony.','Welcome'=>'Witamy','Please wait while we load the welcome page...'=>'Proszę czekać, gdy ładujemy stronę powitalną...','Language pack has not been checked yet.'=>'Pakiet językowy nie został jeszcze sprawdzony.','Site locale is English. No language pack is downloaded.'=>'Locale witryny to angielski. Żaden pakiet językowy nie został pobrany.','No language packs are registered.'=>'Nie zarejestrowano żadnych pakietów językowych.','Language pack directory is not available.'=>'Katalog pakietów językowych jest niedostępny.','Language pack for %1$s (%2$s) matches %3$s.'=>'Pakiet językowy dla %1$s (%2$s) pasuje do %3$s.','Language pack for %1$s (%2$s) installed for %3$s.'=>'Pakiet językowy dla %1$s (%2$s) zainstalowany dla %3$s.','Language pack URL was rejected.'=>'Adres URL pakietu językowego został odrzucony.','Language pack download failed for %1$s (%2$s). The installed pack was left in place.'=>'Pobranie pakietu językowego nie powiodło się dla %1$s (%2$s). Zainstalowany pakiet pozostał na miejscu.','Language pack could not be unpacked.'=>'Pakiet językowy nie mógł zostać rozpakowany.','Language pack is missing a catalog file. The installed pack was left in place.'=>'Pakiet językowy nie zawiera pliku katalogowego. Zainstalowany pakiet pozostał na miejscu.','Language pack JSON catalog is invalid. The installed pack was left in place.'=>'Katalog JSON pakietu językowego jest nieprawidłowy. Zainstalowany pakiet pozostał na miejscu.','Language pack could not be stored. The installed pack was left in place.'=>'Pakiet językowy nie mógł być zapisany. Zainstalowany pakiet pozostał na miejscu.','Language pack PHP catalog could not be built. The installed pack was left in place.'=>'Katalog PHP pakietu językowego nie mógł być zbudowany. Zainstalowany pakiet pozostał na miejscu.','Warning: The license for %1$s has expired. %2$s'=>'Ostrzeżenie: Licencja dla %1$s wygasła. %2$s','Manage licenses'=>'Zarządzaj licencjami','Warning: %1$d plugin(s) have expired licenses: %2$s. %3$s'=>'Ostrzeżenie: %1$d wtyczka(i) mają wygasłe licencje: %2$s. %3$s','The license server accepted your key, but this site could not save its active license. Please contact support and mention this message.'=>'Serwer licencji zaakceptował Twój klucz, ale ta witryna nie mogła zapisać swojej aktywnej licencji. Proszę skontaktować się z pomocą techniczną i wspomnieć o tej wiadomości.','PublishPress actions for %s. These tools apply only to this site. If several sites are connected and the requested site is unclear, ask which site to use before calling a tool. Confirm the target site before changing site data.'=>'Akcje PublishPress dla %s. Te narzędzia mają zastosowanie tylko do tej witryny. Jeśli wiele witryn jest połączonych, a żądana witryna jest niejasna, zapytaj, którą witrynę użyć przed wywołaniem narzędzia. Potwierdź docelową witrynę przed zmianą danych witryny.','WordPress version'=>'Wersja WordPressa','MCP Adapter version'=>'Wersja adaptera MCP','Not active'=>'Nieaktywny','HTTPS'=>'HTTPS','Available'=>'Dostępny','Required'=>'Wymagany','Application passwords'=>'Hasła aplikacji','Unavailable; check WordPress or security plugin settings'=>'Niedostępne; sprawdź ustawienia WordPressa lub wtyczek zabezpieczających','Registered actions'=>'Zarejestrowane akcje','Selected actions exposed'=>'Wybrane akcje ujawnione','Changes saved.'=>'Zmiany zapisane.','Changes saved. Restart your AI app or refresh its PublishPress connection to update the available actions.'=>'Zmiany zapisane. Uruchom ponownie swoją aplikację AI lub odśwież jej połączenie z PublishPress, aby zaktualizować dostępne akcje.','Changes saved. Connect your AI app to continue.'=>'Zmiany zapisane. Połącz swoją aplikację AI, aby kontynuować.','Changes saved. Select at least one available action to continue.'=>'Zmiany zapisane. Wybierz przynajmniej jedną dostępną akcję, aby kontynuować.','Update WordPress to continue'=>'Zaktualizuj WordPress, aby kontynuować','WordPress 6.9 or newer is required.'=>'Wymagana jest wersja WordPress 6.9 lub nowsza.','Open WordPress updates'=>'Otwórz aktualizacje WordPress','Install the MCP Adapter plugin'=>'Zainstaluj wtyczkę MCP Adapter','Install the official WordPress MCP Adapter plugin to connect your AI service.'=>'Zainstaluj oficjalną wtyczkę MCP Adapter WordPress, aby połączyć swoją usługę AI.','Manage plugins'=>'Zarządzaj wtyczkami','Set up MCP Adapter'=>'Skonfiguruj MCP Adapter','Use HTTPS to connect your AI'=>'Użyj HTTPS, aby połączyć swoją AI','Both WordPress and site addresses must use HTTPS.'=>'Zarówno adresy WordPress, jak i strony muszą korzystać z HTTPS.','Open site settings'=>'Otwórz ustawienia witryny','Add a PublishPress plugin with AI actions'=>'Dodaj wtyczkę PublishPress z akcjami AI','You don\'t have any PublishPress plugins installed that support AI actions yet.'=>'Nie masz jeszcze zainstalowanych żadnych wtyczek PublishPress, które obsługują akcje AI.','Open PublishPress plugins'=>'Otwórz wtyczki PublishPress','Allow application passwords for your account'=>'Zezwól na hasła aplikacji dla swojego konta','Create an application password in your WordPress profile for assisted or manual setup.'=>'Utwórz hasło aplikacji w swoim profilu WordPress dla pomocy lub ręcznej konfiguracji.','Application passwords are unavailable for your account. HTTPS or security plugin settings may need attention.'=>'Hasła aplikacji są niedostępne dla twojego konta. Ustawienia HTTPS lub wtyczki zabezpieczającej mogą wymagać uwagi.','Open application passwords'=>'Otwórz hasła aplikacji','PASTE_YOUR_APPLICATION_PASSWORD_HERE'=>'WKLEJ_TUTAJ_SWOJE_HASŁO_APLIKACJI','Ask my AI to help'=>'Poproś moją AI o pomoc','Recommended. Ask your AI for a setup script to run on your computer.'=>'Zalecane. Poproś swoją AI o skrypt konfiguracyjny do uruchomienia na swoim komputerze.','Connect my AI app to PublishPress. Create a setup script and give me the exact terminal command to run it.

1. Ask me to select my AI app and OS (Windows, macOS or Linux). Use interactive choices if available, otherwise numbered options.
2. Create the script using your file tools. Request the specific permission if needed. If you cannot write locally, attach a downloadable script. Only fall back to code with save instructions when neither is possible. Use PowerShell on Windows and an appropriate script on macOS or Linux. Do not stop at explaining access limitations or provide only JSON.
3. Configure this local stdio server:
Name: %3$s
Display name: %4$s
Command: npx
Arguments: -y @automattic/mcp-wordpress-remote@latest
Environment: OAUTH_ENABLED=false, WP_API_URL=%1$s, WP_API_USERNAME=%2$s
Read WP_API_PASSWORD through a hidden terminal prompt.
Hub write access: %5$s. Only individually selected actions are exposed.
4. Check Node.js and npx. If missing, link to the official installer and tell me to reopen the terminal. Back up existing settings. Use a JSON/TOML parser or supported client command to merge only this server, preserving other settings and sites. Stop on invalid configuration or a conflicting endpoint. If replacing an old PublishPress desktop extension for this site, guide me to disable only that extension to avoid duplicate connections. Quote paths and values safely.
5. Give brief run, restart and approval instructions. Verify through the connection or give me a prompt to test in the app: confirm the site URL, list actual tools and perform a read-only lookup. Report whether write tools are available. If expected write tools are missing, ask me to check Allow actions that change site data and the selected actions in Hub, then refresh the connection. Do not claim success from saved configuration alone. Do not test writes during setup. Clarify the target site when ambiguous and ask for review before changing site data.'=>'Połącz moją aplikację AI z PublishPress. Utwórz skrypt konfiguracyjny i podaj mi dokładne polecenie terminala do jego uruchomienia.

1. Poproś mnie o wybór mojej aplikacji AI i systemu operacyjnego (Windows, macOS lub Linux). Użyj interaktywnych wyborów, jeśli są dostępne, w przeciwnym razie opcji numerowanych.
2. Utwórz skrypt za pomocą swoich narzędzi plikowych. Poproś o odpowiednie uprawnienia, jeśli to konieczne. Jeśli nie możesz pisać lokalnie, dołącz skrypt do pobrania. Użyj PowerShell na Windows i odpowiedniego skryptu na macOS lub Linux. Nie przerywaj na wyjaśnianiu ograniczeń dostępu ani nie podawaj tylko JSON-a.
3. Skonfiguruj ten lokalny serwer stdio:
Nazwa: %3$s
Nazwa wyświetlana: %4$s
Polecenie: npx
Argumenty: -y @automattic/mcp-wordpress-remote@latest
Środowisko: OAUTH_ENABLED=false, WP_API_URL=%1$s, WP_API_USERNAME=%2$s
Przeczytaj WP_API_PASSWORD przez ukryty monit terminala.
Dostęp do zapisu w hubie: %5$s. Tylko indywidualnie wybrane akcje są ujawnione.
4. Sprawdź Node.js i npx. Jeśli brakuje, podaj link do oficjalnego instalatora i powiedz mi, aby ponownie otworzył terminal. Zrób kopię zapasową istniejących ustawień. Użyj parsera JSON/TOML lub obsługiwanej komendy klienta, aby połączyć tylko ten serwer, zachowując inne ustawienia i witryny. Przerwij w przypadku nieprawidłowej konfiguracji lub konfliktującego punktu końcowego. Jeśli zastępujesz starą rozszerzenie desktopowe PublishPress dla tej witryny, poprowadź mnie, aby wyłączyć tylko to rozszerzenie, aby uniknąć podwójnych połączeń. Cytuj ścieżki i wartości bezpiecznie.
5. Podaj krótkie instrukcje uruchamiania, ponownego uruchamiania i zatwierdzania. Zweryfikuj przez połączenie lub daj mi monit do przetestowania w aplikacji: potwierdź adres URL witryny, wymień aktualne narzędzia i wykonaj wyszukiwanie tylko do odczytu. Zgłoś, czy narzędzia do zapisu są dostępne. Jeśli oczekiwane narzędzia do zapisu są niedostępne, poproś mnie o sprawdzenie Zezwól na akcje, które zmieniają dane witryny oraz wybrane akcje w Hubie, a następnie odśwież połączenie. Nie twierdź, że udało się to tylko na podstawie zapisanej konfiguracji. Nie testuj zapisów podczas konfiguracji. Wyjaśnij docelową witrynę, gdy jest niejednoznaczna, i poproś o przegląd przed zmianą danych witryny.</source>
<t i="30">włączony','disabled'=>'wyłączony','Set up manually'=>'Skonfiguruj ręcznie','Copy the configuration into your MCP client.'=>'Skopiuj konfigurację do swojego klienta MCP.','Actions available through PublishPress Hub.'=>'Akcje dostępne przez PublishPress Hub.','List WordPress users'=>'Lista użytkowników WordPress','Find users by name or role. The optional primitive capability filter checks effective access within each candidate page. Visit all total_pages even when a filtered page is empty. No email addresses or secrets are returned.'=>'Znajdź użytkowników według nazwy lub roli. Opcjonalny filtr zdolności prymitywnej sprawdza efektywny dostęp w każdej kandydującej stronie. Odwiedź wszystkie total_pages, nawet gdy strona filtrująca jest pusta. Żadne adresy e-mail ani sekrety nie są zwracane.','Get WordPress user capabilities'=>'Uzyskaj zdolności użytkowników WordPress','Resolve exactly one user_id or username and return their identity, roles and effective primitive capabilities. Never guess a user ID. Object-specific permissions require a separate check for that object.'=>'Rozwiąż dokładnie jeden user_id lub nazwę użytkownika i zwróć ich tożsamość, role i efektywne prymitywne zdolności. Nigdy nie zgaduj identyfikatora użytkownika. Uprawnienia specyficzne dla obiektu wymagają oddzielnego sprawdzenia dla tego obiektu.','Find WordPress content'=>'Znajdź treści WordPress','Search readable posts, pages or a REST-enabled custom post type. Returns actual IDs, titles and permalinks. Use post_type=page for pages. Resolve ambiguous titles before using a URL. Default status is publish. Private and draft requests enforce WordPress permissions.'=>'Szukaj czytelnych postów, stron lub niestandardowego typu postu z włączonym REST. Zwraca rzeczywiste identyfikatory, tytuły i permalinki. Użyj post_type=page dla stron. Rozwiąż niejednoznaczne tytuły przed użyciem adresu URL. Domyślny status to publikacja. Prywatne i robocze żądania egzekwują uprawnienia WordPress.','List WordPress post types'=>'Lista typów postów WordPress','List readable REST-enabled post types and the capability names used for each type. Use these names for content lookups and permission questions.'=>'Lista czytelnych typów postów z włączonym REST i nazw zdolności używanych dla każdego typu. Użyj tych nazw do wyszukiwania treści i pytań o uprawnienia.','WordPress'=>'WordPress','Create WordPress user'=>'Utwórz użytkownika WordPress','Create a new user account with a known username, email and one editable role. Ask for missing details. WordPress validates role assignment permissions. MCP rejects administrator and any role granting administrator-level capabilities. A password is generated privately. By default WordPress emails the user a password setup link. Never guess an email or request a password in chat.'=>'Utwórz nowe konto użytkownika z znaną nazwą użytkownika, adresem e-mail i jedną edytowalną rolą. Poproś o brakujące szczegóły. WordPress weryfikuje uprawnienia do przypisywania ról. MCP odrzuca administratora i wszelkie role przyznające uprawnienia na poziomie administratora. Hasło jest generowane prywatnie. Domyślnie WordPress wysyła użytkownikowi link do ustawienia hasła. Nigdy nie zgaduj adresu e-mail ani nie żądaj hasła w czacie.','Create WordPress content'=>'Utwórz zawartość WordPress','Create a post, page or REST-enabled custom post type. Use post_type=page for pages. Defaults to draft. Publish or schedule only when requested. WordPress checks creation, publishing and author-assignment permissions. Returns the actual ID and permalink.'=>'Utwórz post, stronę lub niestandardowy typ postu obsługujący REST. Użyj post_type=page dla stron. Domyślnie jest to szkic. Publikuj lub planuj tylko na żądanie. WordPress sprawdza uprawnienia do tworzenia, publikowania i przypisywania autora. Zwraca faktyczne ID i permalink.','Update WordPress content'=>'Aktualizuj zawartość WordPress','Edit an existing post, page or REST-enabled custom post by its verified ID. Find content first if the ID is unknown. Only supplied fields change. WordPress checks object, publishing and author-assignment permissions. No deletion, arbitrary metadata or options are supported.'=>'Edytuj istniejący post, stronę lub niestandardowy post obsługujący REST według jego zweryfikowanego ID. Najpierw znajdź zawartość, jeśli ID jest nieznane. Tylko dostarczone pola ulegają zmianie. WordPress sprawdza uprawnienia do obiektów, publikacji i przypisywania autora. Nie obsługiwane są usunięcia, dowolne metadane ani opcje.','Use the exact input types shown in discovery.'=>'Użyj dokładnych typów wejściowych pokazanych w odkryciu.','You cannot list users.'=>'Nie możesz wymieniać użytkowników.','Provide either a user ID or an exact username.'=>'Podaj albo ID użytkownika, albo dokładną nazwę użytkownika.','No matching user belongs to this site.'=>'Żaden odpowiadający użytkownik nie należy do tej witryny.','You cannot inspect this user.'=>'Nie możesz sprawdzić tego użytkownika.','Choose a REST-enabled post type.'=>'Wybierz typ postu obsługujący REST.','This post type does not support content lookup.'=>'Ten typ postu nie obsługuje wyszukiwania zawartości.','MCP tools cannot create users with administrator-level access. Use the WordPress Users screen for this change.'=>'Narzędzia MCP nie mogą tworzyć użytkowników z dostępem na poziomie administratora. Użyj ekranu Użytkownicy WordPress do tej zmiany.','Provide at least one content field to update.'=>'Podaj przynajmniej jedno pole zawartości do zaktualizowania.','Choose an existing REST-enabled post type.'=>'Wybierz istniejący typ postu obsługujący REST.','This post type does not support content writes.'=>'Ten typ postu nie obsługuje zapisów zawartości.','You cannot perform this operation.'=>'Nie możesz wykonać tej operacji.','Object must be loaded before initializing.'=>'Obiekt musi być załadowany przed inicjalizacją.','This license key is managed in wp-config.php and cannot be edited from the Hub.'=>'Ten klucz licencyjny jest zarządzany w wp-config.php i nie może być edytowany z poziomu Hub.','No license key found'=>'Nie znaleziono klucza licencyjnego','This license key is managed in wp-config.php and cannot be deactivated from the Hub.'=>'Ten klucz licencyjny jest zarządzany w wp-config.php i nie może być dezaktywowany z poziomu Hub.','Invalid conflict resolution request.'=>'Nieprawidłowa prośba o rozwiązanie konfliktu.','The selected plugin is not available for activation.'=>'Wybrany wtyczka nie jest dostępna do aktywacji.','Cleanup was stopped because the selected plugin is not active or the other version is still loaded. Neither copy was deleted.'=>'Czyszczenie zostało zatrzymane, ponieważ wybrany wtyczka nie jest aktywna lub inna wersja jest nadal załadowana. Żadna kopia nie została usunięta.','The selected plugin is active, but the other version could not be removed. Please remove it from the Plugins screen.'=>'Wybrany wtyczka jest aktywna, ale inna wersja nie mogła zostać usunięta. Proszę usunąć ją z ekranu Wtyczki.','The selected plugin is no longer active. Please reactivate it from the Plugins screen.'=>'Wybrany wtyczka nie jest już aktywna. Proszę ponownie ją aktywować z ekranu Wtyczki.','No existing license key was found for this plugin.'=>'Nie znaleziono istniejącego klucza licencyjnego dla tej wtyczki.','Database Tables'=>'Tabele bazy danych','PublishPress Plugins'=>'Wtyczki PublishPress','PublishPress Hub Debug Log'=>'Dziennik debugowania Hub PublishPress','Debug Log'=>'Dziennik debugowania','The debug log is empty.'=>'Dziennik debugowania jest pusty.','Version'=>'Wersja','Debug Mode'=>'Tryb debugowania','Enabled'=>'Włączony','Disabled'=>'Wyłączony','Generated At'=>'Wygenerowano o','Plugins'=>'Wtyczki','No PublishPress plugins found.'=>'Nie znaleziono wtyczek PublishPress.','Tables'=>'Tabele','No database table information was available.'=>'Nie było dostępnych informacji o tabeli bazy danych.','Size'=>'Rozmiar','Engine'=>'Silnik','Rows'=>'Wiersze','Collation'=>'Porządek','Charset'=>'Zestaw znaków','Total Database Size'=>'Całkowity rozmiar bazy danych','Not installed'=>'Nie zainstalowano','Active'=>'Aktywny','Inactive'=>'Nieaktywny','unknown'=>'nieznany','License'=>'Licencja','Free plugin not set for plugin family: %s'=>'Nie ustawiono darmowej wtyczki dla rodziny wtyczek: %s','Pro plugin not set for plugin family: %s'=>'Nie ustawiono płatnej wtyczki dla rodziny wtyczek: %s','License activation error. Please try again later or contact support for help.'=>'Błąd aktywacji licencji. Spróbuj ponownie później lub skontaktuj się z pomocą techniczną w celu uzyskania pomocy.','License deactivation error. Please try again later or contact support for help.'=>'Błąd dezaktywacji licencji. Spróbuj ponownie później lub skontaktuj się z pomocą techniczną w celu uzyskania pomocy.','This license is currently disabled. Please contact support for help.'=>'Ta licencja jest obecnie wyłączona. Skontaktuj się z pomocą techniczną w celu uzyskania pomocy.','This license has expired. Please contact support to renew it.'=>'Ta licencja wygasła. Skontaktuj się z pomocą techniczną w celu jej odnowienia.','This license key could not be activated. It may be invalid, blocked, or not authorized for this plugin. Please verify the key and contact PublishPress support if the problem continues.'=>'Nie można aktywować tego klucza licencyjnego. Może być nieprawidłowy, zablokowany lub nieautoryzowany dla tej wtyczki. Sprawdź klucz i skontaktuj się z pomocą techniczną PublishPress, jeśli problem się utrzymuje.','This license cannot be used for this plugin. Please contact support for help.'=>'Ta licencja nie może być użyta dla tej wtyczki. Skontaktuj się z pomocą techniczną w celu uzyskania pomocy.','This license does not match the plugin you are trying to activate. Please contact support for assistance.'=>'Ta licencja nie pasuje do wtyczki, którą próbujesz aktywować. Skontaktuj się z pomocą techniczną w celu uzyskania pomocy.','License key does not match our records. Please contact support for assistance.'=>'Klucz licencyjny nie pasuje do naszych zapisów. Skontaktuj się z pomocą techniczną w celu uzyskania pomocy.','No license key provided. Please enter a valid license key.'=>'Nie podano klucza licencyjnego. Wprowadź prawidłowy klucz licencyjny.','Your site URL is required to activate the license. Please enter a valid site URL to continue.'=>'Adres URL Twojej witryny jest wymagany do aktywacji licencji. Wprowadź prawidłowy adres URL witryny, aby kontynuować.','License activation limit reached. Please contact support to upgrade or deactivate on another site.'=>'Osiągnięto limit aktywacji licencji. Skontaktuj się z pomocą techniczną, aby przeprowadzić aktualizację lub dezaktywować na innej witrynie.','This license cannot be activated. Please contact support for help.'=>'Ta licencja nie może być aktywowana. Skontaktuj się z pomocą techniczną w celu uzyskania pomocy.','License server error. Please try again later or contact support for help.'=>'Błąd serwera licencji. Spróbuj ponownie później lub skontaktuj się z pomocą techniczną w celu uzyskania pomocy.','The license server returned an invalid response. Please try again later or contact support for help.'=>'Serwer licencji zwrócił nieprawidłową odpowiedź. Spróbuj ponownie później lub skontaktuj się z pomocą techniczną w celu uzyskania pomocy.','This license is inactive for this site. Please contact support for help.'=>'Ta licencja jest nieaktywna dla tej witryny. Skontaktuj się z pomocą techniczną w celu uzyskania pomocy.','Plugin activation failed. Please try again later or contact support for help.'=>'Aktywacja wtyczki nie powiodła się. Spróbuj ponownie później lub skontaktuj się z pomocą techniczną w celu uzyskania pomocy.','This action is not possible because the plugin is already installed.'=>'Ta akcja nie jest możliwa, ponieważ wtyczka jest już zainstalowana.','Plugin deactivation failed. Please try again later or contact support for help.'=>'Dezaktywacja wtyczki nie powiodła się. Spróbuj ponownie później lub skontaktuj się z pomocą techniczną w celu uzyskania pomocy.','Plugin family not found. Please contact support for help.'=>'Rodzina wtyczek nie została znaleziona. Skontaktuj się z pomocą techniczną w celu uzyskania pomocy.','This action is not possible because both free and pro versions are installed. Please uninstall one version to continue.'=>'Ta akcja nie jest możliwa, ponieważ zainstalowane są zarówno wersje darmowe, jak i płatne. Odinstaluj jedną wersję, aby kontynuować.','Plugin installation failed. Please contact support for help.'=>'Instalacja wtyczki nie powiodła się. Skontaktuj się z pomocą techniczną w celu uzyskania pomocy.','This action is not possible because the plugin is not activated. Please activate the plugin and try again.'=>'Ta akcja nie jest możliwa, ponieważ wtyczka nie jest aktywowana. Aktywuj wtyczkę i spróbuj ponownie.','Plugin not found in our available plugins list. Please contact support for help.'=>'Wtyczka nie została znaleziona na naszej liście dostępnych wtyczek. Skontaktuj się z pomocą techniczną w celu uzyskania pomocy.','This action is not possible because the plugin is not installed. Please install the plugin and try again.'=>'Ta akcja nie jest możliwa, ponieważ wtyczka nie jest zainstalowana. Zainstaluj wtyczkę i spróbuj ponownie.','Unknown license server error. Please try again later or contact support for help.'=>'Nieznany błąd serwera licencji. Spróbuj ponownie później lub skontaktuj się z pomocą techniczną w celu uzyskania pomocy.','Sell digital products, programs, and services from your website.'=>'Sprzedawaj produkty cyfrowe, programy i usługi z swojej strony internetowej.','Create and manage tags, categories, and taxonomy terms.'=>'Twórz i zarządzaj tagami, kategoriami oraz terminami taksonomii.','Organize taxonomy terms into groups and display them in clouds, tabs, and lists.'=>'Organizuj terminy taksonomii w grupy i wyświetlaj je w chmurach, zakładkach i listach.','Define tasks that authors must complete before publishing.'=>'Definiuj zadania, które autorzy muszą wykonać przed publikacją.','Control who can edit and view your content.'=>'Kontroluj, kto może edytować i przeglądać Twoje treści.','Create, manage and display authors for your content.'=>'Twórz, zarządzaj i wyświetlaj autorów dla swoich treści.','All the tools you need to improve the block editor.'=>'Wszystkie narzędzia, których potrzebujesz, aby poprawić edytor bloków.','Control your admin area and user roles.'=>'Kontroluj swój obszar administracyjny i role użytkowników.','Schedule changes to your posts.'=>'Zaplanuj zmiany w swoich postach.','Organize, schedule, and plan your publishing.'=>'Organizuj, planuj i harmonogramuj swoje publikacje.','Approve and schedule new versions to your published posts.'=>'Zatwierdzaj i planuj nowe wersje swoich opublikowanych postów.','Organize your posts into issues or series.'=>'Organizuj swoje posty w numery lub serie.','Create custom URLs for your posts and external links.'=>'Twórz niestandardowe URL-e dla swoich postów i linków zewnętrznych.','Create custom statuses and publishing workflows.'=>'Twórz niestandardowe statusy i przepływy pracy publikacji.','Dependency "%s" not found in container.'=>'Zależność "%s" nie została znaleziona w kontenerze.','Error validating license: %s'=>'Błąd weryfikacji licencji: %s','Error getting license info: %s'=>'Błąd podczas pobierania informacji o licencji: %s','The license server denied this request. This can happen when a license key or site has been blocked. Please contact PublishPress support for help.'=>'Serwer licencji odrzucił tę prośbę. Może się to zdarzyć, gdy klucz licencyjny lub strona zostały zablokowane. Skontaktuj się z pomocą techniczną PublishPress w celu uzyskania pomocy.','Too many requests. Please try again later.'=>'Zbyt wiele żądań. Spróbuj ponownie później.','An error occurred while processing your request.'=>'Wystąpił błąd podczas przetwarzania Twojej prośby.','Template not found: %s'=>'Szablon nie został 